// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 warpTime, uint256 unlockTime, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        warpTime = bound(warpTime, 1, type(uint256).max / 2);
        unlockTime = bound(unlockTime, 0, type(uint256).max / 2);

        vm.warp(warpTime);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Put{value: 1 wei}(unlockTime);

        (uint256 storedUnlockTime,) = c.Acc(actor);
        assertTrue(storedUnlockTime >= block.timestamp);
    }
}
